export interface DiagramTemplate {
  id: string;
  name: string;
  code: string;
  icon: string;
}

export enum EditorTheme {
  LIGHT = 'light',
  DARK = 'dark'
}

export interface HistoryItem {
  id: string;
  timestamp: number;
  code: string;
  name: string;
}

import { GoogleGenAI } from "@google/genai";

export const generateDiagramFromText = async (prompt: string): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const systemInstruction = `
    You are an expert Mermaid.js engineer. 
    Your task is to take a user's description and generate the most appropriate Mermaid.js diagram code.
    - ONLY return the Mermaid code block.
    - Do NOT include markdown backticks like \`\`\`mermaid or \`\`\`.
    - Ensure the syntax is correct.
    - If the user wants to refine an existing diagram, apply those changes.
    - Default to 'graph TD' if no specific type is mentioned unless the context suggests otherwise (sequence, gantt, etc).
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        systemInstruction,
        temperature: 0.7,
      },
    });

    const text = response.text || '';
    // Clean up any stray backticks just in case
    return text.replace(/```mermaid/g, '').replace(/```/g, '').trim();
  } catch (error) {
    console.error("AI Generation Error:", error);
    throw new Error("Failed to generate diagram. Please check your prompt and try again.");
  }
};

import React from 'react';

interface EditorProps {
  code: string;
  onChange: (value: string) => void;
}

const Editor: React.FC<EditorProps> = ({ code, onChange }) => {
  const lineCount = code.split('\n').length;

  return (
    <div className="flex h-full w-full bg-slate-900 overflow-hidden shadow-inner">
      <div className="hidden sm:flex flex-col items-end pt-4 pr-2 pl-3 bg-slate-800 text-slate-500 font-mono text-sm select-none border-r border-slate-700 w-12 shrink-0">
        {Array.from({ length: Math.max(lineCount, 20) }).map((_, i) => (
          <div key={i} className="leading-6">{i + 1}</div>
        ))}
      </div>
      <textarea
        className="flex-1 bg-transparent text-slate-100 font-mono text-sm leading-6 p-4 focus:outline-none resize-none overflow-auto custom-scrollbar"
        value={code}
        onChange={(e) => onChange(e.target.value)}
