export default Editor;

import React, { useEffect, useRef, useState } from 'react';

interface PreviewProps {
  code: string;
}

const Preview: React.FC<PreviewProps> = ({ code }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [error, setError] = useState<string | null>(null);
  const [svg, setSvg] = useState<string>('');

  useEffect(() => {
    // @ts-ignore
    if (window.mermaid) {
      // @ts-ignore
      window.mermaid.initialize({
        startOnLoad: false,
        theme: 'default',
        securityLevel: 'loose',
        fontFamily: 'Inter',
        flowchart: { htmlLabels: true, curve: 'basis' },
      });
    }
  }, []);

  useEffect(() => {
    const renderDiagram = async () => {
      if (!containerRef.current || !code.trim()) {
        setSvg('');
        setError(null);
        return;
      }

      try {
        setError(null);
        const id = `mermaid-render-${Date.now()}`;
        // @ts-ignore
        const { svg: renderedSvg } = await window.mermaid.render(id, code);
        setSvg(renderedSvg);
      } catch (err: any) {
        console.error("Mermaid Rendering Error:", err);
        setError("Invalid Mermaid syntax. Please check your code.");
      }
    };

    const timeoutId = setTimeout(renderDiagram, 300);
    return () => clearTimeout(timeoutId);
  }, [code]);

  return (
    <div className="h-full w-full flex flex-col items-center justify-center p-8 overflow-auto bg-white rounded-lg shadow-sm border border-slate-200">
      {error ? (
        <div className="p-4 bg-red-50 border border-red-200 text-red-600 rounded-md text-sm font-medium animate-pulse">
          {error}
        </div>
      ) : svg ? (
        <div 
          className="mermaid w-full flex justify-center" 
          dangerouslySetInnerHTML={{ __html: svg }} 
        />
      ) : (
        <div className="text-slate-400 italic">No diagram to display</div>
      )}
    </div>
  );
};

export default Preview;

import React, { useState, useEffect, useCallback } from 'react';
import Editor from './components/Editor';
import Preview from './components/Preview';
import { DEFAULT_DIAGRAM, TEMPLATES } from './constants';
import { generateDiagramFromText } from './services/geminiService';

const App: React.FC = () => {
  const [code, setCode] = useState<string>(DEFAULT_DIAGRAM);
  const [isAiLoading, setIsAiLoading] = useState(false);
