  useEffect(() => {
    localStorage.setItem('mermaid_code', code);
  }, [code]);

  const handleAiGenerate = async () => {
    if (!aiPrompt.trim()) return;

    setIsAiLoading(true);
    try {
      const generatedCode = await generateDiagramFromText(`Generate a Mermaid diagram for: ${aiPrompt}. Current diagram code: ${code}`);
      setCode(generatedCode);
      setAiPrompt('');
