            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16m-7 6h7" /></svg>
            Templates
          </button>
          <div className="h-4 w-px bg-slate-200 mx-1"></div>
          <button 
            onClick={copyToClipboard}
            className="px-3 py-1.5 text-sm font-medium text-slate-700 hover:bg-slate-100 rounded-md transition-colors"
          >
            Copy Code
          </button>
          <button 
            onClick={handleExportSvg}
            className="px-4 py-1.5 text-sm font-bold text-white bg-indigo-600 hover:bg-indigo-700 rounded-md transition-all shadow-md active:scale-95"
          >
            Export SVG
          </button>
        </div>
      </header>

      <div className="flex flex-1 overflow-hidden relative">
        {/* Templates Dropdown Overlay */}
        {showTemplates && (
          <div className="absolute top-4 right-6 w-64 bg-white shadow-2xl rounded-xl border border-slate-200 z-50 p-3 overflow-hidden animate-in fade-in zoom-in duration-200">
            <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest px-2 mb-2">Templates</h3>
            <div className="space-y-1">
              {TEMPLATES.map(t => (
                <button
                  key={t.id}
                  onClick={() => { setCode(t.code); setShowTemplates(false); }}
                  className="w-full text-left px-3 py-2 text-sm text-slate-700 hover:bg-indigo-50 hover:text-indigo-700 rounded-lg flex items-center gap-3 transition-colors group"
                >
                  <span className="text-lg">{t.icon}</span>
                  <span className="font-medium">{t.name}</span>
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Main Workspace */}
        <div className="flex flex-1 flex-col md:flex-row overflow-hidden">

          {/* AI Sidebar */}
          <div className={`transition-all duration-300 ${isSidebarOpen ? 'w-full md:w-80' : 'w-0 overflow-hidden'} bg-white border-r border-slate-200 flex flex-col shrink-0`}>
            <div className="p-4 flex-1 overflow-y-auto space-y-6">
              <div>
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest block mb-3">AI Assistant</label>
                <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 space-y-3">
                  <p className="text-sm text-slate-600 leading-relaxed">
