              </div>

              <div>
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest block mb-3">Current Diagram Info</label>
                <div className="text-sm text-slate-600 bg-slate-100 p-3 rounded-lg border border-slate-200">
                  <div className="flex justify-between mb-1">
                    <span>Lines:</span>
                    <span className="font-mono text-indigo-600 font-bold">{code.split('\n').length}</span>
                  </div>
                  <div className="flex justify-between">
                    <span>Characters:</span>
                    <span className="font-mono text-indigo-600 font-bold">{code.length}</span>
                  </div>
                </div>
              </div>
            </div>

            <div className="p-4 border-t border-slate-200 bg-slate-50 text-[10px] text-slate-400 text-center uppercase tracking-tighter font-medium">
              Powered by Gemini 3 Pro & Mermaid.js
            </div>
          </div>

          {/* Toggle Button for Sidebar */}
          <button 
            onClick={() => setIsSidebarOpen(!isSidebarOpen)}
            className="absolute left-[320px] top-1/2 -translate-y-1/2 z-20 w-6 h-12 bg-white border border-slate-200 border-l-0 rounded-r-lg flex items-center justify-center text-slate-400 hover:text-indigo-600 shadow-sm hidden md:flex transition-all"
            style={{ left: isSidebarOpen ? '320px' : '0px' }}
