            <svg className={`w-4 h-4 transition-transform ${isSidebarOpen ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7" /></svg>
          </button>

          {/* Editor & Preview Area */}
          <div className="flex flex-1 flex-col overflow-hidden">
            <div className="flex-1 flex flex-col lg:flex-row overflow-hidden">
