                  Live Preview
                </div>
                <Preview code={code} />
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState } from 'react';

interface PreviewProps {
  code: string;
}

const Preview: React.FC<PreviewProps> = ({ code }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [error, setError] = useState<string | null>(null);
  const [svg, setSvg] = useState<string>('');

  useEffect(() => {
    // @ts-ignore
    if (window.mermaid) {
      // @ts-ignore
      window.mermaid.initialize({
        startOnLoad: false,
        theme: 'default',
        securityLevel: 'loose',
        fontFamily: 'Inter',
        flowchart: { htmlLabels: true, curve: 'basis' },
      });
    }
  }, []);

  useEffect(() => {
    const renderDiagram = async () => {
      // Basic validation
      if (!code || !code.trim()) {
        setSvg('');
        setError(null);
        return;
      }

      // Ensure mermaid is available on the window object
      // @ts-ignore
      if (!window.mermaid) {
        setError("Mermaid library failed to load. Please refresh the page.");
        return;
      }

      try {
        setError(null);
        // Each render needs a unique ID
        const id = `mermaid-render-${Math.random().toString(36).substr(2, 9)}`;

        // Use the mermaid.render API (Version 10+)
        // @ts-ignore
        const { svg: renderedSvg } = await window.mermaid.render(id, code);
        setSvg(renderedSvg);
      } catch (err: any) {
        console.error("Mermaid Rendering Error:", err);
        // Mermaid errors can be messy, we try to show a cleaner message
        setError("Invalid Mermaid syntax. Check your code or try a template.");

        // If we have an error, we might want to clear the old SVG 
        // but often it's better to keep it so the user sees what broke
      }
    };

    // Debounce the rendering to prevent lag while typing
    const timeoutId = setTimeout(renderDiagram, 300);
    return () => clearTimeout(timeoutId);
  }, [code]);

  return (
    <div 
      ref={containerRef}
      className="h-full w-full flex flex-col items-center justify-center p-8 overflow-auto bg-white rounded-lg shadow-sm border border-slate-200"
    >
      {error ? (
        <div className="flex flex-col items-center gap-4 text-center max-w-md">
          <div className="p-4 bg-red-50 border border-red-200 text-red-600 rounded-lg text-sm font-medium">
            <p className="font-bold mb-1">Syntax Error</p>
            {error}
          </div>
          <p className="text-xs text-slate-400">Diagram will update automatically as you fix the code.</p>
        </div>
      ) : svg ? (
        <div 
          className="mermaid-container w-full flex justify-center" 
          dangerouslySetInnerHTML={{ __html: svg }} 
        />
      ) : (
        <div className="flex flex-col items-center gap-2 text-slate-400">
          <svg className="w-12 h-12 opacity-20" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
          </svg>
          <span className="italic">Type code or use AI to generate a diagram</span>
        </div>
      )}
    </div>
  );
};

export default Preview;

import { GoogleGenAI } from "@google/genai";

export const generateDiagramFromText = async (prompt: string, currentCode: string): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const systemInstruction = `
    You are an expert Mermaid.js architect. 
    Your goal is to provide valid, high-quality Mermaid.js code based on user requests.

    CRITICAL RULES:
    1. ONLY return the Mermaid code block itself.
    2. NEVER include markdown backticks (like \`\`\`mermaid or \`\`\`).
    3. If the user asks to modify the existing diagram, apply the changes to the provided "Current Code".
    4. If the user asks for something entirely new, generate it from scratch.
    5. Ensure the syntax is strictly correct for Mermaid.js.
    6. Do not include any conversational text, just the code.
  `;

  const fullPrompt = `
    CURRENT DIAGRAM CODE:
    ${currentCode}

    USER REQUEST:
    ${prompt}

    Please provide the updated or new Mermaid.js code:
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: fullPrompt,
      config: {
        systemInstruction,
        temperature: 0.4, // Lower temperature for more stable code generation
      },
    });

    const text = response.text || '';
    // Clean up any stray backticks just in case the model ignores instructions
    return text.replace(/```mermaid/g, '').replace(/```/g, '').trim();
  } catch (error) {
    console.error("AI Generation Error:", error);
    throw new Error("Failed to process your request. Please try again.");
  }
};

import React, { useState, useEffect, useRef } from 'react';
import Editor from './components/Editor';
import Preview from './components/Preview';
import { DEFAULT_DIAGRAM, TEMPLATES } from './constants';
import { generateDiagramFromText } from './services/geminiService';

const App: React.FC = () => {
  const [code, setCode] = useState<string>(DEFAULT_DIAGRAM);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [aiPrompt, setAiPrompt] = useState('');
  const [showTemplates, setShowTemplates] = useState(false);
  const [chatLog, setChatLog] = useState<{role: 'user' | 'ai', message: string}[]>([]);
  const chatEndRef = useRef<HTMLDivElement>(null);

  // Sync with local storage
  useEffect(() => {
    const saved = localStorage.getItem('mermaid_code');
    if (saved) setCode(saved);
  }, []);

  useEffect(() => {
    localStorage.setItem('mermaid_code', code);
  }, [code]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatLog, isAiLoading]);

  const handleAiAction = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!aiPrompt.trim() || isAiLoading) return;

    const userMsg = aiPrompt;
    setChatLog(prev => [...prev, { role: 'user', message: userMsg }]);
    setAiPrompt('');
    setIsAiLoading(true);

    try {
      const generatedCode = await generateDiagramFromText(userMsg, code);
      setCode(generatedCode);
      setChatLog(prev => [...prev, { role: 'ai', message: 'Diagram updated successfully! ✨' }]);
    } catch (err) {
      setChatLog(prev => [...prev, { role: 'ai', message: 'Sorry, I encountered an error updating the diagram.' }]);
    } finally {
      setIsAiLoading(false);
    }
  };

  const handleExportSvg = () => {
    const svgElement = document.querySelector('.mermaid-container svg');
    if (!svgElement) return;

    const svgData = new XMLSerializer().serializeToString(svgElement);
    const blob = new Blob([svgData], { type: 'image/svg+xml;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = 'diagram.svg';
    link.click();
    URL.revokeObjectURL(url);
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(code).then(() => {
      alert('Code copied to clipboard!');
    });
  };

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-slate-50">
      {/* Header */}
      <header className="h-14 flex items-center justify-between px-6 bg-white border-b border-slate-200 z-10 shrink-0">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-indigo-600 rounded flex items-center justify-center text-white font-bold text-lg shadow-sm">
            M
          </div>
          <div>
            <h1 className="text-sm font-bold text-slate-900 leading-tight">MermaidAI Pro</h1>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <button 
            onClick={() => setShowTemplates(!showTemplates)}
            className="px-3 py-1 text-xs font-semibold text-slate-600 hover:bg-slate-100 rounded transition-colors flex items-center gap-1.5"
          >
            <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16m-7 6h7" /></svg>
            Templates
          </button>
          <div className="h-4 w-px bg-slate-200 mx-1"></div>
          <button 
            onClick={copyToClipboard}
            className="px-3 py-1 text-xs font-semibold text-slate-600 hover:bg-slate-100 rounded transition-colors"
          >
            Copy
          </button>
          <button 
            onClick={handleExportSvg}
            className="px-4 py-1.5 text-xs font-bold text-white bg-indigo-600 hover:bg-indigo-700 rounded transition-all shadow-sm active:scale-95"
          >
            Export SVG
          </button>
        </div>
      </header>

      <div className="flex flex-1 overflow-hidden relative">
        {/* Templates Dropdown Overlay */}
        {showTemplates && (
          <div className="absolute top-2 right-4 w-60 bg-white shadow-xl rounded-lg border border-slate-200 z-50 p-2 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
            <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-2 py-1">Quick Start</h3>
            <div className="space-y-0.5">
              {TEMPLATES.map(t => (
                <button
