import React, { useEffect, useRef, useState } from 'react';

interface PreviewProps {
  code: string;
  zoom: number;
}

const Preview: React.FC<PreviewProps> = ({ code, zoom }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [error, setError] = useState<string | null>(null);
  const [svg, setSvg] = useState<string>('');

  useEffect(() => {
    // @ts-ignore
    if (window.mermaid) {
      // @ts-ignore
      window.mermaid.initialize({
        startOnLoad: false,
        theme: 'default',
        securityLevel: 'loose',
        fontFamily: 'Inter',
        flowchart: { htmlLabels: true, curve: 'basis' },
      });
    }
  }, []);

  useEffect(() => {
    const renderDiagram = async () => {
      if (!code || !code.trim()) {
        setSvg('');
        setError(null);
        return;
      }

      // @ts-ignore
      if (!window.mermaid) {
        setError("Mermaid library failed to load. Please refresh the page.");
        return;
      }

      try {
        setError(null);
        const id = `mermaid-render-${Math.random().toString(36).substr(2, 9)}`;
        // @ts-ignore
        const { svg: renderedSvg } = await window.mermaid.render(id, code);
        setSvg(renderedSvg);
      } catch (err: any) {
        console.error("Mermaid Rendering Error:", err);
        setError("Invalid Mermaid syntax. Check your code or try a template.");
      }
    };

    const timeoutId = setTimeout(renderDiagram, 300);
    return () => clearTimeout(timeoutId);
  }, [code]);

  return (
    <div 
      ref={containerRef}
      className="h-full w-full flex flex-col items-center justify-center overflow-auto bg-white rounded-lg shadow-sm border border-slate-200 relative transition-all duration-200"
    >
      {error ? (
        <div className="flex flex-col items-center gap-4 text-center max-w-md p-8">
          <div className="p-4 bg-red-50 border border-red-200 text-red-600 rounded-lg text-sm font-medium">
            <p className="font-bold mb-1">Syntax Error</p>
            {error}
          </div>
          <p className="text-xs text-slate-400">Diagram will update automatically as you fix the code.</p>
        </div>
      ) : svg ? (
        <div 
          className="mermaid-container w-full h-full flex items-center justify-center p-8 transition-transform duration-200 origin-center"
          style={{ transform: `scale(${zoom})` }}
          dangerouslySetInnerHTML={{ __html: svg }} 
        />
      ) : (
        <div className="flex flex-col items-center gap-2 text-slate-400 p-8">
          <svg className="w-12 h-12 opacity-20" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
          </svg>
          <span className="italic">Type code or use AI to generate a diagram</span>
        </div>
      )}
    </div>
  );
};

export default Preview;

