            Templates
          </button>
          <div className="h-4 w-px bg-slate-700 mx-1"></div>
          <button 
            onClick={copyToClipboard}
            className="px-3 py-1.5 text-xs font-semibold text-slate-400 hover:text-slate-100 hover:bg-slate-800 rounded transition-all"
