import { GoogleGenAI } from "@google/genai";

const cleanMermaidCode = (text: string): string => {
  // Remove markdown code blocks and common prefix/suffixes
  return text
    .replace(/```mermaid\n?/g, '')
    .replace(/```\n?/g, '')
    .trim();
};

export const generateDiagramFromText = async (prompt: string, currentCode: string): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `
    You are an expert Mermaid.js architect. 
    Your goal is to provide valid, high-quality Mermaid.js code based on user requests.

    CRITICAL SYNTAX RULES:
    1. ONLY return the Mermaid code block. No explanation. No backticks.
    2. Comments must start with DOUBLE percentage signs (%%). NEVER use a single %.
    3. Labels with spaces or special characters (like "đầu ra khác") are safer when enclosed in quotes if they cause issues, but Mermaid flowchart labels like "|text|" are usually fine unless they contain restricted symbols.
    4. Ensure every node used in a relationship is defined or follows the standard syntax: ID[Label] or ID(Label).
    5. Statements can end with a newline or a semicolon, but be consistent.
    6. For flowcharts, the direction is usually 'graph TD' or 'graph LR'.
  `;

  const fullPrompt = `
    CURRENT DIAGRAM CODE:
    ${currentCode}

    USER REQUEST:
    ${prompt}

    Please provide the updated or new Mermaid.js code:
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: fullPrompt,
      config: {
        systemInstruction,
        temperature: 0.4,
      },
    });

    return cleanMermaidCode(response.text || '');
  } catch (error) {
    console.error("AI Generation Error:", error);
    throw new Error("Failed to process your request. Please try again.");
  }
};

export const fixMermaidSyntax = async (brokenCode: string, errorMessage: string): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `
    You are a specialized Mermaid.js syntax repair expert.
    You will be given broken Mermaid code and the specific error message from the parser.

    COMMON FIXES YOU MUST APPLY:
    1. Replace single '%' comments with double '%%'. This is a very frequent error.
    2. Ensure labels in flowcharts following the '|label|' syntax do not contain characters that confuse the parser (e.g., semicolons or unquoted special chars).
    3. If a semicolon is causing a 'got NODE_STRING' error, it might be misplaced or redundant—remove it or ensure it properly terminates the statement before a newline or comment.
    4. Ensure node IDs do not contain spaces unless the node is declared with a label: ID["Label with spaces"].
    5. Return ONLY the fixed Mermaid code. No backticks. No talk.
  `;

  const fullPrompt = `
    BROKEN CODE:
    ${brokenCode}

    ERROR MESSAGE:
    ${errorMessage}

    Fixed Mermaid code:
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: fullPrompt,
      config: {
        systemInstruction,
        temperature: 0.1, // Very low for deterministic fixing
      },
    });

    return cleanMermaidCode(response.text || '');
  } catch (error) {
    console.error("AI Fix Error:", error);
    throw new Error("Failed to autofix syntax.");
  }
};

import React, { useRef, useEffect } from 'react';

interface EditorProps {
  code: string;
  onChange: (value: string) => void;
}

const highlightMermaid = (code: string) => {
  // Escape HTML
  let html = code
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");

  // Highlighting regexes
  const tokens = [
    // Comments
    { regex: /(%%.*)/g, class: 'text-slate-500 italic' },
    // Diagram Types & Keywords
    { regex: /\b(graph|flowchart|sequenceDiagram|classDiagram|erDiagram|gantt|pie|gitGraph|stateDiagram|journey|info|TD|LR|TB|BT|RL|subgraph|end|participant|actor|as|loop|alt|else|opt|rect|note|over|left of|right of|activate|deactivate|title|section|class|style|linkStyle|click|callback|direction)\b/g, class: 'text-indigo-400 font-bold' },
    // Arrows & Connectors
    { regex: /(--&gt;|--|--&gt;&gt;|-&gt;|-&gt;&gt;|--\)|-\)|-x|--x|==&gt;|==|~~|~|&lt;--|&lt;-|&lt;==|&lt;--&gt;)/g, class: 'text-amber-500' },
    // Brackets and Shapes
    { regex: /(\[|\]|\(|\)|\{|\}|&gt;)/g, class: 'text-purple-400' },
    // Node Labels/Strings
    { regex: /(&quot;.*?&quot;)/g, class: 'text-emerald-400' },
    // Decision Labels
    { regex: /\|(.*?)\|/g, class: 'text-sky-400 italic' }
  ];

  tokens.forEach(token => {
    html = html.replace(token.regex, `<span class="${token.class}">$1</span>`);
  });

  return html;
};

const Editor: React.FC<EditorProps> = ({ code, onChange }) => {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const preRef = useRef<HTMLPreElement>(null);
  const lineCount = code.split('\n').length;

  // Sync scroll
  const handleScroll = () => {
    if (textareaRef.current && preRef.current) {
      preRef.current.scrollTop = textareaRef.current.scrollTop;
      preRef.current.scrollLeft = textareaRef.current.scrollLeft;
    }
  };

  useEffect(() => {
    handleScroll();
  }, [code]);

  return (
    <div className="flex h-full w-full bg-slate-900 overflow-hidden relative">
      {/* Line Numbers */}
      <div className="hidden sm:flex flex-col items-end pt-4 pr-2 pl-3 bg-slate-950 text-slate-700 font-mono text-[10px] select-none border-r border-slate-800 w-10 shrink-0 z-10">
        {Array.from({ length: Math.max(lineCount, 30) }).map((_, i) => (
          <div key={i} className="leading-6 h-6">{i + 1}</div>
        ))}
      </div>

      <div className="relative flex-1 h-full overflow-hidden">
        {/* Highlighted Overlay */}
        <pre
          ref={preRef}
          aria-hidden="true"
          className="absolute inset-0 m-0 p-4 pointer-events-none font-mono text-sm leading-6 whitespace-pre overflow-hidden"
          dangerouslySetInnerHTML={{ __html: highlightMermaid(code) + '\n' }}
        />

        {/* Real Textarea */}
        <textarea
          ref={textareaRef}
          className="absolute inset-0 w-full h-full bg-transparent text-transparent caret-white font-mono text-sm leading-6 p-4 focus:outline-none resize-none overflow-auto custom-scrollbar"
          value={code}
          onChange={(e) => onChange(e.target.value)}
          onScroll={handleScroll}
          spellCheck={false}
          autoCapitalize="none"
          autoComplete="off"
          autoCorrect="off"
          placeholder="Type your mermaid code here..."
        />
      </div>
    </div>
  );
};

