/**
 * Highlights Mermaid syntax in a single pass to avoid nested tag replacement.
 */
const highlightMermaid = (code: string) => {
  // 1. Escape basic HTML entities first
  let escaped = code
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");

  // 2. Define tokens in order of precedence
  // We use capturing groups to identify which token matched
  const tokens = [
    { name: 'comment', regex: /(%%.*)/ },
    { name: 'string', regex: /(".*?")/ },
    { name: 'pipe-label', regex: /(\|.*\|)/ },
    { name: 'keyword', regex: /\b(graph|flowchart|sequenceDiagram|classDiagram|erDiagram|gantt|pie|gitGraph|stateDiagram|journey|info|TD|LR|TB|BT|RL|subgraph|end|participant|actor|as|loop|alt|else|opt|rect|note|over|left of|right of|activate|deactivate|title|section|class|style|linkStyle|click|callback|direction)\b/ },
    { name: 'arrow', regex: /(-->|--|-->>|->|->>|--\)|-\)|-x|--x|==>|==|~~|~|<--|<-|<==|<-->)/ },
    { name: 'bracket', regex: /(\[|\]|\(|\)|\{|\}|>)/ },
  ];

  // Combine into one large regex
  const combinedRegex = new RegExp(tokens.map(t => t.regex.source).join('|'), 'g');

  // 3. Single-pass replacement
  return escaped.replace(combinedRegex, (match) => {
    // Determine which token it was
    if (match.startsWith('%%')) return `<span class="text-slate-500 italic">${match}</span>`;
    if (match.startsWith('"')) return `<span class="text-emerald-400 font-medium">${match}</span>`;
    if (match.startsWith('|')) return `<span class="text-sky-400">${match}</span>`;

    // Check keywords (this is a bit simplified, but since it's single pass, it won't hit our injected tags)
    const isKeyword = tokens.find(t => t.name === 'keyword')?.regex.test(match);
    if (isKeyword) return `<span class="text-indigo-400 font-bold">${match}</span>`;

    const isArrow = tokens.find(t => t.name === 'arrow')?.regex.test(match);
    if (isArrow) return `<span class="text-amber-500 font-medium">${match}</span>`;

    const isBracket = tokens.find(t => t.name === 'bracket')?.regex.test(match);
    if (isBracket) return `<span class="text-purple-400 font-bold">${match}</span>`;

    return match;
  });
};

