  const handleAutofix = async (errorMsg: string) => {
    if (isAiLoading) return;
    setIsAiLoading(true);
    try {
      const fixedCode = await fixMermaidSyntax(code, errorMsg);
      setCode(fixedCode);
    } catch (err) {
      console.error(err);
      alert('AI could not fix the syntax automatically. Please check the code.');
