import { GoogleGenAI } from "@google/genai";

const cleanMermaidCode = (text: string): string => {
  // Remove markdown code blocks and common prefix/suffixes
  return text
    .replace(/```mermaid\n?/g, '')
    .replace(/```\n?/g, '')
    .trim();
};

export const generateDiagramFromText = async (prompt: string, currentCode: string): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `
    You are an expert Mermaid.js architect. 
    Your goal is to provide valid, high-quality Mermaid.js code based on user requests.

    CRITICAL SYNTAX RULES TO AVOID "NODE_STRING" ERRORS:
    1. ONLY return the Mermaid code block. No explanation. No backticks.
    2. MANDATORY LINK ARROWS: A label |"text"| MUST ALWAYS be preceded by an arrow.
       CORRECT: A -->|"Label"| B
       INCORRECT: A |"Label"| B (This is the #1 cause of NODE_STRING errors)
    3. NO SEMICOLONS: Never use semicolons (;) at the end of lines. Use newlines only.
    4. NO SINGLE PERCENT COMMENTS: Comments must start with DOUBLE percentage signs (%%).
       INCORRECT: % Comment
       CORRECT: %% Comment
    5. NO TRAILING TEXT: Never place random text or identifiers after a node definition.
       BAD: C{"Label"} azz
       GOOD: C{"Label"}
    6. ONE STATEMENT PER LINE: Ensure every relationship is on its own line.
    7. QUOTE ALL LABELS: Always wrap text labels in DOUBLE QUOTES.
       Example: ID["Label text"] or -->|"Link text"|
    8. For flowcharts:
       - Use 'graph TD' or 'graph LR'.
       - Use arrows like '-->' or '==>'.
  `;

  const fullPrompt = `
    CURRENT DIAGRAM CODE:
    ${currentCode}

    USER REQUEST:
    ${prompt}

    Please provide the updated or new Mermaid.js code. 
    REMARK: If adding links with labels, ensure the syntax is exactly: Node1 -->|"Label"| Node2
    Ensure every statement is on its own line. NEVER use semicolons. NEVER use single % comments.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: fullPrompt,
      config: {
        systemInstruction,
        temperature: 0.2,
      },
    });

    return cleanMermaidCode(response.text || '');
  } catch (error) {
    console.error("AI Generation Error:", error);
    throw new Error("Failed to process your request. Please try again.");
  }
};

export const fixMermaidSyntax = async (brokenCode: string, errorMessage: string): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `
    You are a specialized Mermaid.js syntax repair expert.
    You will be given broken Mermaid code and the specific error message from the parser.

    REQUIRED FIXES for "NODE_STRING" errors:
    1. MISSING ARROWS: Find lines like "Node |Label| Node". Change them to "Node -->|\"Label\"| Node". Every pipe-label must have an arrow BEFORE it.
    2. STRAY TEXT: Remove any "ghost" text like 'aaa', 'azz', or identifiers that appear after a node definition.
    3. BAN SEMICOLONS: Delete all semicolons (;) from the code.
    4. FIX COMMENTS: Change single '%' to double '%%'. Ensure comments are on their own lines.
    5. QUOTE LABELS: Ensure every label inside brackets or pipes is wrapped in double quotes.
    6. NEWLINES: Ensure each relationship or node definition is on a NEW LINE.

    Return ONLY the fixed Mermaid code. No backticks. No talk.
  `;

  const fullPrompt = `
    BROKEN CODE:
    ${brokenCode}

    ERROR MESSAGE:
    ${errorMessage}

    Fixed Mermaid code (fix missing arrows before labels, remove semicolons, fix comments):
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: fullPrompt,
      config: {
        systemInstruction,
        temperature: 0.1,
      },
    });

    return cleanMermaidCode(response.text || '');
  } catch (error) {
    console.error("AI Fix Error:", error);
    throw new Error("Failed to autofix syntax.");
  }
};

import React, { useEffect, useRef, useState, useCallback } from 'react';

interface PreviewProps {
  code: string;
  zoom: number;
  onZoomChange: (newZoom: number) => void;
  onAutofix?: (error: string) => void;
  isFixing?: boolean;
}

const Preview: React.FC<PreviewProps> = ({ code, zoom, onZoomChange, onAutofix, isFixing }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [error, setError] = useState<string | null>(null);
  const [svg, setSvg] = useState<string>('');

  // Pan state
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const dragStart = useRef({ x: 0, y: 0 });

  useEffect(() => {
    // @ts-ignore
    if (window.mermaid) {
      // @ts-ignore
      window.mermaid.initialize({
        startOnLoad: false,
        theme: 'default',
        securityLevel: 'loose',
        fontFamily: 'Inter',
        logLevel: 5, // Suppress most logs
        suppressErrorConsole: true,
        flowchart: { htmlLabels: false, curve: 'basis' },
        sequence: { htmlLabels: false },
        class: { htmlLabels: false },
        state: { htmlLabels: false },
      });

      // Override the default parse error handler to prevent Mermaid from 
      // injecting its own error div into the body.
      // @ts-ignore
      window.mermaid.parseError = (err: any) => {
        // We handle errors in the catch block of the render process
        console.debug("Mermaid Parse Error Intercepted");
      };
    }
  }, []);

  useEffect(() => {
    const renderDiagram = async () => {
      if (!code || !code.trim()) {
        setSvg('');
        setError(null);
        return;
      }

      // @ts-ignore
      if (!window.mermaid) {
        setError("Mermaid library failed to load. Please refresh the page.");
        return;
      }

      try {
        setError(null);
        const id = `mermaid-render-${Math.random().toString(36).substr(2, 9)}`;

        // Use mermaid.parse first to validate before attempting a render
        // @ts-ignore
        await window.mermaid.parse(code);

        // @ts-ignore
        const { svg: renderedSvg } = await window.mermaid.render(id, code);
        setSvg(renderedSvg);
      } catch (err: any) {
        console.error("Mermaid Render Error:", err);

        // Deep cleaning of the error message to remove Mermaid versioning and other boilerplate
        const rawMsg = err.message || String(err);

        // Specifically target and remove "mermaid version X.Y.Z" and any redundant prefixes
        const cleanMsg = rawMsg
          .replace(/mermaid version \d+\.\d+\.\d+/gi, '') // Remove version string
          .split('mermaid version')[0] // Fallback safety split
          .replace(/\n\s*\n/g, '\n') // Remove excessive empty lines
          .trim();

        setError(cleanMsg || "Invalid Mermaid syntax. Please check your code.");
      }
    };

    const timeoutId = setTimeout(renderDiagram, 300);
    return () => clearTimeout(timeoutId);
  }, [code]);

  // Handle Wheel Zoom
  const handleWheel = useCallback((e: React.WheelEvent) => {
    if (e.ctrlKey || e.metaKey) {
      e.preventDefault();
      const delta = e.deltaY > 0 ? -0.1 : 0.1;
      const newZoom = Math.min(Math.max(zoom + delta, 0.1), 5);
      onZoomChange(newZoom);
    } else {
      e.preventDefault();
      const delta = e.deltaY > 0 ? -0.05 : 0.05;
      const newZoom = Math.min(Math.max(zoom + delta, 0.1), 5);
      onZoomChange(newZoom);
    }
  }, [zoom, onZoomChange]);

  // Handle Mouse Pan
  const handleMouseDown = (e: React.MouseEvent) => {
    if (e.button !== 0) return; // Only left click
    setIsDragging(true);
    dragStart.current = { x: e.clientX - offset.x, y: e.clientY - offset.y };
  };

  const handleMouseMove = useCallback((e: MouseEvent) => {
    if (!isDragging) return;
    setOffset({
      x: e.clientX - dragStart.current.x,
      y: e.clientY - dragStart.current.y
    });
  }, [isDragging]);

  const handleMouseUp = useCallback(() => {
    setIsDragging(false);
  }, []);

  useEffect(() => {
    if (isDragging) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
    } else {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    }
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging, handleMouseMove, handleMouseUp]);

  return (
    <div 
      ref={containerRef}
      onWheel={handleWheel}
      onMouseDown={handleMouseDown}
      className={`h-full w-full flex flex-col items-center justify-center overflow-hidden bg-white rounded-lg shadow-sm border border-slate-200 relative ${isDragging ? 'cursor-grabbing' : 'cursor-grab'}`}
    >
      {error ? (
        <div className="flex flex-col items-center gap-4 text-center max-w-md p-8 z-[100] bg-white rounded-xl shadow-xl border border-red-100 m-4 animate-in fade-in zoom-in duration-200">
          <div className="w-12 h-12 bg-red-100 text-red-600 rounded-full flex items-center justify-center mb-2 shrink-0">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
            </svg>
          </div>
          <div className="text-red-700 w-full overflow-hidden">
            <h3 className="font-bold text-lg mb-2">Syntax Error</h3>
            <div className="p-3 bg-red-50 border border-red-100 rounded-md text-xs font-mono break-words max-h-48 overflow-auto custom-scrollbar text-left">
              {error}
            </div>

            {onAutofix && (
              <button 
                onClick={() => onAutofix(error)}
                disabled={isFixing}
                className="mt-6 w-full flex items-center justify-center gap-2 py-3 px-6 bg-indigo-600 text-white rounded-lg text-sm font-bold hover:bg-indigo-700 transition-all shadow-lg active:scale-95 disabled:opacity-50"
              >
                <svg className={`w-4 h-4 ${isFixing ? 'animate-spin' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" />
                </svg>
                {isFixing ? 'AI Fixing...' : 'Autofix with Gemini'}
              </button>
            )}
          </div>
          <p className="text-[10px] text-slate-400 mt-2 uppercase tracking-widest font-bold">Please correct the syntax to refresh preview</p>
        </div>
      ) : svg ? (
        <div 
          className="mermaid-container w-full h-full flex items-center justify-center transition-transform duration-75 origin-center"
          style={{ 
            transform: `translate(${offset.x}px, ${offset.y}px) scale(${zoom})`,
            pointerEvents: isDragging ? 'none' : 'auto'
          }}
          dangerouslySetInnerHTML={{ __html: svg }} 
        />
      ) : (
        <div className="flex flex-col items-center gap-2 text-slate-400 p-8 pointer-events-none">
          <svg className="w-12 h-12 opacity-20" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
          </svg>
          <span className="italic">Type code or use AI to generate a diagram</span>
        </div>
      )}

      {!error && (
        <div className="absolute bottom-2 left-1/2 -translate-x-1/2 text-[9px] text-slate-300 font-medium tracking-wide uppercase pointer-events-none">
          Scroll to Zoom • Drag to Pan
        </div>
      )}
    </div>
  );
};

export default Preview;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import Editor from './components/Editor';
import Preview from './components/Preview';
import { DEFAULT_DIAGRAM, TEMPLATES } from './constants';
import { generateDiagramFromText, fixMermaidSyntax } from './services/geminiService';

const App: React.FC = () => {
  const [code, setCode] = useState<string>(DEFAULT_DIAGRAM);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [aiPrompt, setAiPrompt] = useState('');
  const [showTemplates, setShowTemplates] = useState(false);

  // UI State
  const [isEditorVisible, setIsEditorVisible] = useState(true);
  const [leftPanelWidth, setLeftPanelWidth] = useState(40); // Percentage
  const [previewZoom, setPreviewZoom] = useState(1);
  const [isResizing, setIsResizing] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const templatesRef = useRef<HTMLDivElement>(null);
  const templatesButtonRef = useRef<HTMLButtonElement>(null);

  // Sync with local storage
  useEffect(() => {
    const saved = localStorage.getItem('mermaid_code');
    if (saved) setCode(saved);
  }, []);

  useEffect(() => {
    localStorage.setItem('mermaid_code', code);
  }, [code]);

  // Handle click outside for templates
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        showTemplates &&
        templatesRef.current &&
        !templatesRef.current.contains(event.target as Node) &&
        templatesButtonRef.current &&
        !templatesButtonRef.current.contains(event.target as Node)
      ) {
        setShowTemplates(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [showTemplates]);

  const handleAiAction = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!aiPrompt.trim() || isAiLoading) return;

    const userMsg = aiPrompt;
    setAiPrompt('');
    setIsAiLoading(true);

    try {
      const generatedCode = await generateDiagramFromText(userMsg, code);
      setCode(generatedCode);
    } catch (err) {
      console.error(err);
      alert('AI failed to process. Try a different prompt.');
    } finally {
      setIsAiLoading(false);
    }
  };

  const handleAutofix = async (errorMsg: string) => {
    if (isAiLoading) return;
    setIsAiLoading(true);
    try {
      const fixedCode = await fixMermaidSyntax(code, errorMsg);
      setCode(fixedCode);
    } catch (err) {
      console.error(err);
      alert('AI could not fix the syntax automatically. Please check the code.');
    } finally {
      setIsAiLoading(false);
    }
  };

  const handleExportSvg = () => {
    const svgElement = document.querySelector('.mermaid-container svg');
    if (!svgElement) return;

    const svgData = new XMLSerializer().serializeToString(svgElement);
    const blob = new Blob([svgData], { type: 'image/svg+xml;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = 'diagram.svg';
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleExportMd = () => {
    const mdContent = `# Mermaid Diagram\n\n\`\`\`mermaid\n${code}\n\`\`\``;
    const blob = new Blob([mdContent], { type: 'text/markdown;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = 'diagram.md';
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleExportPng = () => {
    const svgElement = document.querySelector('.mermaid-container svg') as SVGSVGElement;
    if (!svgElement) {
      alert("No diagram found to export.");
      return;
    }

    // Capture precise SVG dimensions
    const width = svgElement.viewBox.baseVal.width || svgElement.width.baseVal.value || 800;
    const height = svgElement.viewBox.baseVal.height || svgElement.height.baseVal.value || 600;

    // Use a high scale for sharp PNG output
    const scale = 2;
    const canvas = document.createElement('canvas');
    canvas.width = width * scale;
    canvas.height = height * scale;
    const ctx = canvas.getContext('2d');

    if (!ctx) return;

    // Standard serialization with explicit namespaces
    const serializer = new XMLSerializer();
    let svgString = serializer.serializeToString(svgElement);

    // Ensure the SVG string has a proper XML declaration and dimensions
    if (!svgString.match(/^<svg[^>]+xmlns="http\:\/\/www\.w3\.org\/2000\/svg"/)) {
      svgString = svgString.replace(/^<svg/, '<svg xmlns="http://www.w3.org/2000/svg"');
    }

    const svgBlob = new Blob([svgString], { type: 'image/svg+xml;charset=utf-8' });
    const url = URL.createObjectURL(svgBlob);

    const img = new Image();
    // Use crossOrigin to help prevent tainting if external resources were somehow included
    img.crossOrigin = 'anonymous'; 

    img.onload = () => {
      try {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0, width * scale, height * scale);

        const pngUrl = canvas.toDataURL('image/png');
        const downloadLink = document.createElement('a');
        downloadLink.href = pngUrl;
        downloadLink.download = 'diagram.png';
        document.body.appendChild(downloadLink);
        downloadLink.click();
        document.body.removeChild(downloadLink);
      } catch (err) {
        console.error("Export Error:", err);
        alert("Failed to export PNG. This usually happens when the diagram contains complex HTML labels. Try reducing label complexity or using SVG export.");
      } finally {
        URL.revokeObjectURL(url);
      }
    };

    img.onerror = () => {
      console.error("Image loading failed for PNG export.");
      URL.revokeObjectURL(url);
      alert("Failed to process diagram for PNG export.");
    };

    img.src = url;
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(code).then(() => {
      alert('Code copied to clipboard!');
    });
  };

  const startResizing = useCallback(() => setIsResizing(true), []);
  const stopResizing = useCallback(() => setIsResizing(false), []);

  const onResize = useCallback((e: MouseEvent) => {
    if (!isResizing || !containerRef.current) return;
    const containerWidth = containerRef.current.offsetWidth;
    const newWidth = (e.clientX / containerWidth) * 100;
    if (newWidth > 15 && newWidth < 85) {
      setLeftPanelWidth(newWidth);
    }
  }, [isResizing]);

  useEffect(() => {
    window.addEventListener('mousemove', onResize);
    window.addEventListener('mouseup', stopResizing);
    return () => {
      window.removeEventListener('mousemove', onResize);
      window.removeEventListener('mouseup', stopResizing);
    };
  }, [onResize, stopResizing]);

  const toggleEditor = () => setIsEditorVisible(!isEditorVisible);
  const adjustZoom = (delta: number) => setPreviewZoom(prev => Math.min(Math.max(prev + delta, 0.1), 5));
  const resetZoom = () => setPreviewZoom(1);

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-slate-900 select-none">
      <header className="h-14 flex items-center justify-between px-6 bg-slate-900 border-b border-slate-800 z-30 shrink-0">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-indigo-600 rounded flex items-center justify-center text-white font-bold text-lg shadow-sm">
            M
          </div>
          <h1 className="text-sm font-bold text-slate-100 tracking-tight hidden sm:block">MermaidAI Pro</h1>
          <button 
            onClick={toggleEditor}
            className={`ml-4 px-3 py-1 text-xs font-semibold rounded transition-all flex items-center gap-1.5 ${
              isEditorVisible ? 'bg-indigo-600/20 text-indigo-400' : 'bg-slate-800 text-slate-400 hover:text-white'
            }`}
          >
            {isEditorVisible ? 'Hide Editor' : 'Show Editor'}
          </button>
        </div>

        <div className="flex items-center gap-2">
          <button 
            ref={templatesButtonRef}
            onClick={() => setShowTemplates(!showTemplates)}
            className={`px-3 py-1.5 text-xs font-semibold rounded transition-all flex items-center gap-1.5 ${
              showTemplates ? 'text-slate-100 bg-slate-800' : 'text-slate-400 hover:text-slate-100 hover:bg-slate-800'
            }`}
          >
            <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16m-7 6h7" /></svg>
            Templates
          </button>
          <div className="h-4 w-px bg-slate-700 mx-1"></div>
          <button 
            onClick={copyToClipboard}
            className="px-3 py-1.5 text-xs font-semibold text-slate-400 hover:text-slate-100 hover:bg-slate-800 rounded transition-all"
          >
            Copy
          </button>
          <button 
            onClick={handleExportMd}
            className="px-4 py-1.5 text-xs font-bold text-indigo-300 bg-slate-800 hover:bg-slate-700 border border-indigo-500/20 rounded transition-all shadow-lg active:scale-95"
          >
            Export MD
          </button>
          <button 
            onClick={handleExportPng}
            className="px-4 py-1.5 text-xs font-bold text-white bg-indigo-600 hover:bg-indigo-700 rounded transition-all shadow-lg active:scale-95"
          >
            Export PNG
          </button>
          <button 
            onClick={handleExportSvg}
            className="px-4 py-1.5 text-xs font-bold text-white bg-slate-800 hover:bg-slate-700 rounded transition-all shadow-lg active:scale-95"
          >
            Export SVG
          </button>
        </div>
      </header>

      <main ref={containerRef} className="flex flex-1 overflow-hidden relative">
        {showTemplates && (
          <div 
            ref={templatesRef}
            className="absolute top-2 right-4 w-60 bg-slate-800 shadow-2xl rounded-lg border border-slate-700 z-50 p-2 animate-in fade-in slide-in-from-top-2 duration-200"
          >
            <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest px-2 py-1">Sample Diagrams</h3>
            <div className="space-y-0.5">
              {TEMPLATES.map(t => (
                <button
                  key={t.id}
                  onClick={() => { setCode(t.code); setShowTemplates(false); }}
                  className="w-full text-left px-3 py-2 text-xs text-slate-300 hover:bg-indigo-600 hover:text-white rounded flex items-center gap-3 transition-colors group"
                >
                  <span className="text-base">{t.icon}</span>
                  <span className="font-medium">{t.name}</span>
                </button>
              ))}
            </div>
          </div>
        )}

        {isEditorVisible && (
          <div className="flex flex-col min-w-0 border-r border-slate-800 shrink-0" style={{ width: `${leftPanelWidth}%` }}>
            <div className="flex-1 overflow-hidden relative">
               <Editor code={code} onChange={setCode} />
               {isAiLoading && (
                 <div className="absolute inset-0 bg-slate-900/50 backdrop-blur-[1px] flex items-center justify-center z-20 pointer-events-none">
                    <div className="flex flex-col items-center gap-3">
                      <div className="w-8 h-8 border-4 border-indigo-500/30 border-t-indigo-500 rounded-full animate-spin"></div>
                      <span className="text-xs font-bold text-indigo-400 uppercase tracking-widest animate-pulse text-center px-4">AI Processing...</span>
                    </div>
                 </div>
               )}
            </div>

            <div className="p-4 bg-slate-900 border-t border-slate-800 shrink-0">
              <form onSubmit={handleAiAction} className="relative group">
                <div className="absolute -inset-0.5 bg-gradient-to-r from-indigo-500 to-purple-600 rounded-full blur opacity-20 group-hover:opacity-40 transition duration-1000 group-focus-within:opacity-100"></div>
                <div className="relative flex items-center bg-slate-800 rounded-full overflow-hidden border border-slate-700 transition-all focus-within:border-indigo-500/50">
                  <div className="pl-4 text-indigo-400">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" />
                    </svg>
                  </div>
                  <input
                    type="text"
                    value={aiPrompt}
                    onChange={(e) => setAiPrompt(e.target.value)}
                    placeholder="AI modify diagram..."
                    className="flex-1 bg-transparent text-slate-100 text-xs sm:text-sm px-3 py-3 outline-none placeholder:text-slate-500 min-w-0"
                    disabled={isAiLoading}
                  />
                  <button
                    type="submit"
                    disabled={isAiLoading || !aiPrompt.trim()}
                    className={`px-4 py-3 text-[10px] font-bold transition-all shrink-0 ${
                      aiPrompt.trim() && !isAiLoading 
                        ? 'bg-indigo-600 text-white hover:bg-indigo-500' 
                        : 'bg-slate-700 text-slate-500'
                    }`}
                  >
                    Update
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}

        {isEditorVisible && (
          <div 
            className={`w-1 cursor-col-resize hover:bg-indigo-500/50 active:bg-indigo-500 transition-colors z-20 shrink-0 ${isResizing ? 'bg-indigo-500' : 'bg-slate-800'}`}
            onMouseDown={startResizing}
          ></div>
        )}

        <div className="flex-1 bg-slate-50 overflow-hidden flex flex-col relative">
          <div className="absolute bottom-6 right-6 z-20 flex flex-col gap-2">
            <div className="flex bg-white/90 backdrop-blur border border-slate-200 rounded-lg shadow-lg overflow-hidden">
              <button onClick={() => adjustZoom(0.1)} className="p-2 hover:bg-slate-100 text-slate-600 transition-colors" title="Zoom In">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>
              </button>
              <div className="w-px bg-slate-200"></div>
              <button onClick={() => adjustZoom(-0.1)} className="p-2 hover:bg-slate-100 text-slate-600 transition-colors" title="Zoom Out">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20 12H4" /></svg>
              </button>
              <div className="w-px bg-slate-200"></div>
              <button onClick={resetZoom} className="px-3 text-[10px] font-bold text-slate-500 hover:bg-slate-100 transition-colors">
                {Math.round(previewZoom * 100)}%
              </button>
            </div>
          </div>

          <div className="absolute top-4 left-4 z-10 flex gap-2 items-center">
            <span className="px-2 py-1 bg-white/80 backdrop-blur border border-slate-200 rounded text-[10px] font-bold text-slate-400 uppercase tracking-widest shadow-sm">
              Live Render
            </span>
          </div>

          <div className="flex-1 p-4 md:p-8 overflow-hidden select-text">
             <Preview code={code} zoom={previewZoom} onZoomChange={setPreviewZoom} onAutofix={handleAutofix} isFixing={isAiLoading} />
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;
